sys_script.script:
/**
 * Enforce Production Order Quantity Remaining
 *
 * Before Insert/Update Business Rule script.
 * Enforces: quantity_remaining = quantity_planned - quantity_produced
 *
 * Rejects the operation if:
 *   - quantity_planned < 0
 *   - quantity_produced < 0
 *   - quantity_produced > quantity_planned
 *
 * Only sets current.quantity_remaining. Does NOT modify any other
 * field or call current.update().
 */
(function executeRule(current, previous) {
    // Read values, treating blank/null as 0
    var rawPlanned = current.getValue('quantity_planned');
    var rawProduced = current.getValue('quantity_produced');

    var planned = (rawPlanned !== null && rawPlanned !== '') ? parseFloat(rawPlanned) : 0;
    var produced = (rawProduced !== null && rawProduced !== '') ? parseFloat(rawProduced) : 0;

    // Handle NaN from bad data
    if (isNaN(planned)) {
        planned = 0;
    }
    if (isNaN(produced)) {
        produced = 0;
    }

    // Reject negative quantity_planned
    if (planned < 0) {
        gs.addErrorMessage('Production Order rejected: quantity_planned cannot be negative (' + planned + ')');
        current.setAbortAction(true);
        return;
    }

    // Reject negative quantity_produced
    if (produced < 0) {
        gs.addErrorMessage('Production Order rejected: quantity_produced cannot be negative (' + produced + ')');
        current.setAbortAction(true);
        return;
    }

    // Reject quantity_produced > quantity_planned
    if (produced > planned) {
        gs.addErrorMessage(
            'Production Order rejected: quantity_produced (' + produced +
            ') cannot exceed quantity_planned (' + planned + ')'
        );
        current.setAbortAction(true);
        return;
    }

    // Calculate and set the invariant
    var remaining = planned - produced;
    current.setValue('quantity_remaining', remaining.toString());
})(current, previous);
